package com.example.myapplication;

import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.widget.*;
import androidx.activity.result.*;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.content.FileProvider;
import org.json.*;
import java.io.*;
import java.util.concurrent.*;

public class ConversionHistoryActivity extends AppCompatActivity {
    private LinearLayout body;private JSONObject pending;private boolean busy;private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private ActivityResultLauncher<Intent> save;
    @Override public void onCreate(Bundle state){super.onCreate(state);if(state!=null)try{String value=state.getString("pending");if(value!=null)pending=new JSONObject(value);}catch(Exception ignored){}
        save=registerForActivityResult(new ActivityResultContracts.StartActivityForResult(),r->{if(r.getResultCode()==RESULT_OK&&r.getData()!=null&&r.getData().getData()!=null&&pending!=null)save(r.getData().getData());});
        LinearLayout root=new LinearLayout(this);root.setOrientation(android.widget.LinearLayout.VERTICAL);root.setBackgroundColor(AppTheme.background());Button back=new Button(this);back.setText(UiText.get(R.string.ui_back_conversion_history));root.addView(back);back.setOnClickListener(v->finish());ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(android.widget.LinearLayout.VERTICAL);body.setPadding(16,8,16,24);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));UiInsets.apply(root);setContentView(root);
    }
    @Override protected void onResume(){super.onResume();FolderLock.watch(this,this::render);render();}
    private boolean allowed(JSONObject entry){try(DocumentStore store=new DocumentStore(this)){JSONArray folders=entry.optJSONArray("folders");if(folders!=null)for(int i=0;i<folders.length();i++)if(!FolderLock.allowed(this,store,folders.optLong(i)))return false;JSONArray origins=entry.optJSONArray("origins");if(origins!=null)for(int i=0;i<origins.length();i++)try(android.database.Cursor row=store.db().rawQuery("SELECT folder_id FROM docs WHERE path=?",new String[]{origins.optString(i)})){if(row.moveToFirst()&&!FolderLock.allowed(this,store,row.getLong(0)))return false;}return true;}}
    private boolean unlock(JSONObject entry,Runnable next){try{JSONArray folders=entry.optJSONArray("folders");if(folders!=null)try(DocumentStore store=new DocumentStore(this)){for(int i=0;i<folders.length();i++)if(!FolderLock.ensureFolder(this,store,folders.getLong(i),next))return false;}JSONArray origins=entry.optJSONArray("origins");if(origins!=null)for(int i=0;i<origins.length();i++)if(!FolderLock.ensureDocument(this,origins.getString(i),next))return false;return true;}catch(Exception e){toast(e.getMessage());return false;}}
    private void render(){if(isFinishing())return;if(pending!=null&&!allowed(pending))FolderLock.closeDialogs(this);body.removeAllViews();try{JSONArray entries=ConversionHistory.list(this);if(entries.length()==0){TextView empty=new TextView(this);empty.setText(UiText.get(R.string.ui_your_converted_files_will_appear_here_save_to_device_or_share_them_whenever));empty.setTextColor(AppTheme.ink());body.addView(empty);}for(int i=0;i<entries.length();i++){JSONObject entry=entries.getJSONObject(i);Button row=new Button(this);boolean open=allowed(entry);row.setAllCaps(false);row.setText(open ? UiText.format(R.string.ui_value_value, entry.getString("name"), android.text.format.DateFormat.format("dd MMM yyyy HH:mm",entry.getLong("created"))) : UiText.get(R.string.ui_locked_conversion_tap_to_unlock));body.addView(row);row.setOnClickListener(v->actions(entry));}}catch(Exception e){toast(UiText.format(R.string.ui_cannot_load_history_value, e.getMessage()));}}
    private void actions(JSONObject entry){if(busy||!unlock(entry,()->actions(entry)))return;pending=entry;java.util.ArrayList<String> guards=new java.util.ArrayList<>();org.json.JSONArray origins=entry.optJSONArray("origins");if(origins!=null)for(int i=0;i<origins.length();i++)guards.add(origins.optString(i));FolderLock.guardAll(this,guards);new ProtectedDialogs.Builder(this).setTitle(entry.optString("name")).setItems(new String[]{UiText.get(R.string.ui_open), UiText.get(R.string.ui_save_to_device), UiText.get(R.string.ui_share), UiText.get(R.string.ui_delete)},(d,w)->{if(!unlock(entry,()->actions(entry)))return;try{File file=new File(entry.getString("path"));if(w!=3&&!file.isFile())throw new IOException(UiText.get(R.string.ui_converted_file_is_unavailable));Uri uri=FileProvider.getUriForFile(this,getPackageName()+".files",file);if(w==0)startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,entry.getString("mime")).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));else if(w==1)save.launch(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(entry.getString("mime")).putExtra(Intent.EXTRA_TITLE,entry.getString("name")));else if(w==2)startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType(entry.getString("mime")).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),UiText.get(R.string.ui_share_conversion)));else new ProtectedDialogs.Builder(this).setTitle(UiText.get(R.string.ui_delete_converted_file)).setMessage(UiText.get(R.string.ui_the_original_document_is_kept)).setNegativeButton(UiText.get(R.string.ui_cancel),null).setPositiveButton(UiText.get(R.string.ui_delete),(x,y)->{try{ConversionHistory.delete(this,entry.getString("id"));render();}catch(Exception e){toast(e.getMessage());}}).show();}catch(ActivityNotFoundException e){toast(UiText.get(R.string.ui_install_an_app_that_can_open_this_file_or_save_it_to_device));}catch(Exception e){toast(e.getMessage());}}).show();}
    private void save(Uri uri){JSONObject item=pending;if(busy||!unlock(item,()->save(uri)))return;busy=true;worker.execute(()->{String message=UiText.get(R.string.ui_saved_to_device);try(InputStream in=new FileInputStream(item.getString("path"));OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException(UiText.get(R.string.ui_destination_unavailable));byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}catch(Exception e){message=UiText.format(R.string.ui_could_not_save_value, e.getMessage());}String result=message;runOnUiThread(()->{busy=false;toast(result);});});}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(pending!=null)state.putString("pending",pending.toString());}
    @Override protected void onDestroy(){FolderLock.forget(this);worker.shutdown();super.onDestroy();}
    private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
}
